// Layout thrashing: interleaved read/write vs batched read-then-write (fake DOM)
class FakeDom {
  constructor(n) { this.h = new Array(n).fill(10); this.dirty = false; this.reflows = 0; }
  read(i) {                       // reading layout forces a reflow if dirty
    if (this.dirty) { this.reflows++; this.dirty = false; }
    return this.h[i];
  }
  write(i, v) { this.h[i] = v; this.dirty = true; }   // writing marks layout dirty
}
const N = 5;
// Bad: read, write, read, write ... -> every read after a write reflows
const a = new FakeDom(N);
for (let i = 0; i < N; i++) a.write(i, a.read(i) + 5);
console.log('interleaved: heights', a.h.join(','), 'reflows', a.reflows);
// Good: all reads first (layout stays clean), then all writes
const b = new FakeDom(N);
const heights = [];
for (let i = 0; i < N; i++) heights.push(b.read(i));
for (let i = 0; i < N; i++) b.write(i, heights[i] + 5);
b.read(0); // the browser lays out once, when it next needs it
console.log('batched:     heights', b.h.join(','), 'reflows', b.reflows);
// Cost: interleaved = N-1 reflows (every read after a write), batched = 1 reflow, same final result

// Why Core Web Vitals use the 75th percentile, not the average
const lcp = [1.2, 1.3, 1.4, 1.5, 1.6, 1.8, 2.0, 2.2, 6.0, 9.0]; // seconds, 10 visits
const sorted = lcp.slice().sort((x, y) => x - y);
const mean = sorted.reduce((s, v) => s + v, 0) / sorted.length;
// nearest-rank percentile: ceil(p * n)-th smallest value
function percentile(arr, p) { return arr[Math.ceil(p * arr.length) - 1]; }
const p75 = percentile(sorted, 0.75);
const verdict = v => (v <= 2.5 ? 'good' : 'not good');
console.log('LCP samples:', sorted.join(' '));
console.log('mean =', mean.toFixed(2), '->', verdict(mean));   // pulled up by two outliers
console.log('p75  =', p75, '->', verdict(p75));                 // 3 in 4 visits are at least this fast
console.log('median =', percentile(sorted, 0.5));
// Sorting costs O(n log n); the percentile lookup itself is O(1)

// Layout shift score = impact fraction * distance fraction
const viewport = { w: 400, h: 800 };
// An image box 400x200 at the top is pushed down 100px by a late banner
const before = { x: 0, y: 0, w: 400, h: 200 };
const after  = { x: 0, y: 100, w: 400, h: 200 };
function area(r) { return r.w * r.h; }
function overlap(a, b) {
  const w = Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x);
  const h = Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y);
  return Math.max(0, w) * Math.max(0, h);
}
// impact = area covered by the element before OR after, as a share of the viewport
const union = area(before) + area(after) - overlap(before, after);
const impact = union / (viewport.w * viewport.h);
// distance = how far it moved, relative to the larger viewport side
const moved = Math.max(Math.abs(after.x - before.x), Math.abs(after.y - before.y));
const distance = moved / Math.max(viewport.w, viewport.h);
console.log('union area', union, 'impact', impact.toFixed(4));
console.log('moved', moved, 'px distance', distance.toFixed(4));
console.log('shift score', (impact * distance).toFixed(4), '(good is <= 0.1)');

// Virtualized list window for fixed row height
function windowFor(scrollTop, viewportH, rowH, total, overscan) {
  scrollTop = Math.max(0, Math.min(scrollTop, total * rowH - viewportH)); // clamp over-scroll
  let first = Math.floor(scrollTop / rowH);
  let last = Math.ceil((scrollTop + viewportH) / rowH) - 1;
  first = Math.max(0, first - overscan);                 // render a few extra rows
  last = Math.min(total - 1, last + overscan);
  return { first, last, count: last - first + 1, offsetY: first * rowH };
}
const total = 100000, rowH = 40, viewportH = 600;
console.log('spacer height', total * rowH, 'px');
for (const st of [0, 1000, 2_000_000, 4_000_000, 9_999_999]) {
  const w = windowFor(st, viewportH, rowH, total, 3);
  console.log('scrollTop', st, '->', JSON.stringify(w));
}
// Edge case: fewer rows than the viewport
console.log('3 rows:', JSON.stringify(windowFor(0, viewportH, rowH, 3, 3)));
// Cost: O(1) to compute the window, DOM size stays about viewportH/rowH + 2*overscan

// Debounce with a closure timer, plus cancel() and an optional leading call
function debounce(fn, wait, leading) {
  let timer = null;
  function debounced(...args) {
    const callNow = leading && timer === null;
    clearTimeout(timer);                       // every call resets the countdown
    timer = setTimeout(() => {
      timer = null;
      if (!leading) fn.apply(this, args);      // trailing call after quiet period
    }, wait);
    if (callNow) fn.apply(this, args);
  }
  debounced.cancel = () => { clearTimeout(timer); timer = null; };
  return debounced;
}

const log = (label) => (v) => console.log(label, v);
const search = debounce(log('trailing:'), 100, false);
const first = debounce(log('leading: '), 100, true);
// A burst of 4 keystrokes 20ms apart
['h', 'he', 'hel', 'hell'].forEach((v, i) => setTimeout(() => { search(v); first(v); }, i * 20));
// Typing again after a pause starts a new burst
setTimeout(() => { search('hello'); first('hello'); }, 400);
// Result: one trailing call per burst (last value), one leading call per burst (first value)

// How a browser picks an image from srcset with w descriptors
const candidates = [320, 640, 800, 1280, 1920];  // widths of available files
function pick(slotCssWidth, dpr) {
  const needed = slotCssWidth * dpr;             // physical pixels required
  for (const w of candidates) if (w >= needed) return { needed, file: w };
  return { needed, file: candidates[candidates.length - 1] };
}
console.log('sizes="400px" on a 1x screen :', JSON.stringify(pick(400, 1)));
console.log('sizes="400px" on a 2x screen :', JSON.stringify(pick(400, 2)));
console.log('sizes="400px" on a 3x screen :', JSON.stringify(pick(400, 3)));
// Without sizes the browser assumes the slot is 100vw (say 1200px wide)
console.log('no sizes, 1200px viewport 1x :', JSON.stringify(pick(1200, 1)));
